SQL_DOC.P_SQL:
DECLARE
V_COUNT NUMBER;
BEGIN
V_COUNT := 0;
SELECT COUNT(*) INTO V_COUNT FROM KEPIVHD WHERE PLANT = $PLANT$ AND LEGACY_IV_NO = $LEGACY_IV_NO$ AND LEGACY_IV_SEQ = $LEGACY_IV_SEQ$ ;
IF V_COUNT=0 THEN
INSERT INTO KEPIVHD( PLANT , LEGACY_IV_NO , LEGACY_IV_SEQ , STATUS , LEGACY_PO_NO , LEGACY_PO_SEQ , BUYER_ITEM_NO , INV_DATE , ITEM_QTY , UNIT_PRICE , INV_AMT , ADD_DATE, ADD_TIME )VALUES( $PLANT$ , $LEGACY_IV_NO$ , $LEGACY_IV_SEQ$ , $STATUS$ , $LEGACY_PO_NO$ , $LEGACY_PO_SEQ$ , $BUYER_ITEM_NO$ , $INV_DATE$ , $ITEM_QTY$ , $UNIT_PRICE$ , $INV_AMT$ , TO_CHAR(SYSDATE,'YYYYMMDD'), TO_CHAR(SYSDATE,'HH24MISS') );
ELSE
UPDATE KEPIVHD SET STATUS = $STATUS$, LEGACY_PO_NO = $LEGACY_PO_NO$, LEGACY_PO_SEQ = $LEGACY_PO_SEQ$, BUYER_ITEM_NO = $BUYER_ITEM_NO$, INV_DATE = $INV_DATE$, ITEM_QTY = $ITEM_QTY$, UNIT_PRICE = $UNIT_PRICE$, INV_AMT = $INV_AMT$, IF_FLAG = 'N', ADD_DATE = TO_CHAR(SYSDATE,'YYYYMMDD'), ADD_TIME = TO_CHAR(SYSDATE,'HH24MISS') WHERE PLANT = $PLANT$ AND LEGACY_IV_NO = $LEGACY_IV_NO$ AND LEGACY_IV_SEQ = $LEGACY_IV_SEQ$ ;
END IF;
END;
